`src/index.js`:

```javascript
// Research brief template on @kognai/build.
// planRun builds the engine arguments, runTemplate runs the engine and shapes
// what it wrote into the product: brief.md plus run.json.
import { spawn } from 'node:child_process';
import { mkdir, readdir, readFile, stat, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';

export const ENGINE_SUBDIR = 'engine';
export const MAX_BRIEF_CHARS = 2000;
const PROFILES = ['security', 'reliability', 'performance', 'maintainability', 'compatibility', 'usability',
  'portability', 'compliance', 'cost-efficiency', 'time-to-market', 'sovereignty'];
const TEXT_EXT = /\.(md|markdown|txt)$/i;

function cleanText(s) {
  // drop control characters, collapse whitespace, keep the text readable
  return String(s).replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function checkInput(input) {
  if (!input || typeof input !== 'object') throw new Error('input must be an object with a brief');
  if (typeof input.brief !== 'string' || cleanText(input.brief) === '') throw new Error('input.brief must be a non empty string');
  if (input.sovereign !== undefined && typeof input.sovereign !== 'boolean') throw new Error('input.sovereign must be a boolean');
  if (input.audience !== undefined && typeof input.audience !== 'string') throw new Error('input.audience must be a string');
  if (input.profile !== undefined && !PROFILES.includes(input.profile)) throw new Error(`input.profile must be one of: ${PROFILES.join(', ')}`);
}

export function buildGoal(input) {
  const brief = cleanText(input.brief).slice(0, MAX_BRIEF_CHARS);
  const audience = input.audience ? cleanText(input.audience).slice(0, 200) : 'a busy reader new to the topic';
  return [
    `Write a research brief in Markdown on this request: "${brief}".`,
    `Audience: ${audience}.`,
    'Write one file named brief.md with these sections in order:',
    '## Summary (5 sentences at most), ## Key findings (numbered, each with how sure it is),',
    '## Sources (only sources you are sure exist, else say none), ## Open questions.',
    'Mark every claim you cannot support as unverified. Plain words, Latin digits, no long dashes.',
  ].join(' ');
}

export function planRun(input, outDir) {
  checkInput(input);
  if (typeof outDir !== 'string' || outDir === '') throw new Error('outDir must be a non empty path');
  const args = ['--goal', buildGoal(input), '--out-dir', join(outDir, ENGINE_SUBDIR)];
  args.push('--profile', input.profile ?? 'reliability');
  if (input.sovereign === true) args.push('--sovereign');
  return { args };
}

export function defaultExec(args) {
  // npx @kognai/build with the same environment: keys stay in the environment, never in args
  return new Promise((resolve) => {
    const child = spawn('npx', ['-y', '@kognai/build@0.7', ...args], { stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => { stdout += d; });
    child.stderr.on('data', (d) => { stderr += d; });
    child.on('error', (e) => resolve({ code: 127, stdout, stderr: stderr + String(e.message) }));
    child.on('close', (code) => resolve({ code: code ?? 1, stdout, stderr }));
  });
}

export function stripAnsi(s) {
  return String(s ?? '').replace(/\u001b\[[0-9;]*[A-Za-z]/g, '');
}

export function parseCost(stdout) {
  // the engine ends with "Total: <time> · <n> model calls · $0.1234"
  const matches = [...stripAnsi(stdout).matchAll(/Total:[^\n]*?\$(\d+(?:\.\d+)?)/g)];
  return matches.length ? Number(matches[matches.length - 1][1]) : null;
}

async function listTextFiles(dir) {
  const found = [];
  async function walk(d) {
    let entries;
    try { entries = await readdir(d, { withFileTypes: true }); } catch { return; }
    for (const e of entries.sort((a, b) => a.name.localeCompare(b.name))) {
      const p = join(d, e.name);
      if (e.isDirectory()) { if (e.name !== 'node_modules' && !e.name.startsWith('.')) await walk(p); }
      else if (TEXT_EXT.test(e.name) && (await stat(p)).size > 0) found.push(p);
    }
  }
  await walk(dir);
  return found;
}

function lastLine(s) {
  const lines = stripAnsi(s).split('\n').map((l) => l.trim()).filter(Boolean);
  return lines.length ? lines[lines.length - 1].slice(0, 300) : 'no output';
}

export async function runTemplate(input, { outDir, exec = defaultExec } = {}) {
  const { args } = planRun(input, outDir);
  const engineDir = join(outDir, ENGINE_SUBDIR);
  await mkdir(engineDir, { recursive: true });
  let res;
  try { res = await exec(args); } catch (e) { throw new Error(`engine could not start: ${e?.message ?? e}`); }
  if (!res || res.code !== 0) {
    throw new Error(`engine failed with exit code ${res?.code}: ${lastLine(res?.stderr || res?.stdout)}`);
  }
  const sources = await listTextFiles(engineDir);
  if (sources.length === 0) throw new Error(`engine wrote nothing usable into ${engineDir}`);
  // prefer the brief.md the goal asks for, then every other text file in order
  sources.sort((a, b) => Number(/brief\.md$/i.test(b)) - Number(/brief\.md$/i.test(a)));
  const parts = [];
  for (const p of sources) {
    const text = (await readFile(p, 'utf8')).trim();
    if (text) parts.push({ file: relative(engineDir, p), text });
  }
  if (parts.length === 0) throw new Error(`engine wrote only empty files into ${engineDir}`);
  const title = cleanText(input.brief).slice(0, 120);
  const body = parts.map((p, i) => (i === 0 ? p.text : `\n\n## Appendix: ${p.file}\n\n${p.text}`)).join('');
  const parsed = parseCost(res.stdout);
  const cost_usd = input.sovereign ? 0 : (parsed ?? 0);
