```ts
// Golden Kog risk debate. Two advocates argue a token's structure from
// measured facts (sound, fragile), a reviewer weighs them. Risk only: the
// debate never gives a trading view and never returns a level or points.
// Pattern adapted from TradingAgents (TauricResearch, Apache 2.0), without
// its trader or portfolio manager.

export type Role = 'sound' | 'fragile' | 'reviewer';
export type Mode = 'off' | 'shadow' | 'on';

export interface DebateInput {
  facts_text: string;
  level: string;
  points: number;
  flag_ids: string[];
  unknown: string[];
}

export interface RouteArgs {
  task_type: 'risk_debate';
  tier_class: 'text';
  complexity: 'exec' | 'apex';
  context_tokens: number;
  constitutional_flag: false;
  agent_id: 'golden-kog';
  payload: { role: Role; system: string; prompt: string; max_tokens: number };
}

export interface RouteResult {
  content: string;
  model?: string;
  cost_usd?: number;
}

export interface DebateDeps {
  route(args: RouteArgs): Promise<RouteResult>;
  check?(text: string): string[];
  mode?: Mode;
  log?(row: object): void;
  timeoutMs?: number;
}

export interface Debate {
  status: 'ok' | 'rejected' | 'timeout' | 'off';
  shown: boolean;
  sound: string;
  fragile: string;
  reviewer: string;
  weight: string[];
  unknown: string[];
  tension?: string;
  models: { sound?: string; fragile?: string; reviewer?: string };
  usd: number;
  rejected: string[];
}

export const NO_CASE = 'No case could be written from the measured facts.';
export const ADVOCATE_MAX_WORDS = 180;
export const REVIEWER_MAX_WORDS = 150;
export const DEFAULT_TIMEOUT_MS = 45000;

export const REFUSED_WORDS = [
  'bull', 'bear', 'bullish', 'bearish', 'upside', 'downside target',
  'undervalued', 'overvalued', 'accumulate', 'moon', 'buy now', 'sell now',
  'price target', 'entry', 'exit', 'take profit', 'not financial advice',
];

const NUMBER_RE = /\d+(?:[.,]\d+)*/g;
const DASH_RE = /[\p{Pd}−]/u;
const DIGIT_RE = /\p{Nd}/gu;
const REFUSED_RE = REFUSED_WORDS.map(
  (w) => [w, new RegExp(`(?<![\\p{L}\\p{N}])${w.replace(/ /g, '\\s+')}(?![\\p{L}\\p{N}])`, 'iu')] as const,
);

class TimeoutError extends Error {}

function numbersIn(text: string): string[] {
  return text.match(NUMBER_RE) ?? [];
}

export function countWords(text: string): number {
  return text.split(/\s+/).filter((w) => w.length > 0).length;
}

// Every problem of one part against the rules, empty when the part passes.
export function checkPart(
  text: string,
  facts: Set<string>,
  maxWords: number,
  check?: (text: string) => string[],
): string[] {
  const problems: string[] = [];
  for (const n of numbersIn(text)) {
    if (!facts.has(n)) problems.push(`number ${n} is not in the measured facts`);
  }
  for (const [word, re] of REFUSED_RE) {
    if (re.test(text)) problems.push(`refused word: ${word}`);
  }
  if (DASH_RE.test(text)) problems.push('dash character');
  for (const d of text.match(DIGIT_RE) ?? []) {
    if (d < '0' || d > '9') {
      problems.push('non Latin digit');
      break;
    }
  }
  const words = countWords(text);
  if (words > maxWords) problems.push(`${words} words, over ${maxWords}`);
  if (check) for (const p of check(text)) problems.push(`check: ${p}`);
  return problems;
}

const RULES = [
  'Use only the measured facts given. Every number you write must appear in the facts exactly as written there; do not compute new numbers.',
  'This is a risk analysis of the token structure only: no buy or sell view, no price target, no entry or exit, no advice.',
  `Never use these words: ${REFUSED_WORDS.join(', ')}.`,
  'Latin digits only. No dash characters of any kind, not even a hyphen.',
];

function advocateSystem(role: 'sound' | 'fragile'): string {
  const side = role === 'sound'
    ? 'You argue that the token structure is sound.'
    : 'You argue that the token structure is fragile.';
  return [
    `${side} You are one of two advocates in a risk debate for Golden Kog.`,
    ...RULES,
    `At most ${ADVOCATE_MAX_WORDS} words. Plain text.`,
  ].join('\n');
}

function reviewerSystem(): string {
  return [
    'You are the reviewer of a risk debate for Golden Kog. Two advocates argued the token structure from the measured facts; weigh them.',
    ...RULES,
    `Answer only JSON: {"text": string of at most ${REVIEWER_MAX_WORDS} words, "weight": the ids of the risk rules that weigh most, "unknown": what the facts cannot tell, "tension": optional, the main point the advocates disagree on}.`,
  ].join('\n');
}

function factsPrompt(input: DebateInput): string {
  return [
    'Measured facts:',
    input.facts_text,
    `Risk rules that fired: ${input.flag_ids.length ? input.flag_ids.join(', ') : 'none'}`,
    `Not measured: ${input.unknown.length ? input.unknown.join('; ') : 'nothing listed'}`,
  ].join('\n');
}

function routeArgs(role: Role, system: string, prompt: string, maxTokens: number): RouteArgs {
  return {
    task_type: 'risk_debate',
    tier_class: 'text',
    complexity: role === 'reviewer' ? 'apex' : 'exec',
    context_tokens: Math.ceil((system.length + prompt.length) / 4),
    constitutional_flag: false,
    agent_id: 'golden-kog',
    payload: { role, system, prompt, max_tokens: maxTokens },
  };
}

function parseReviewer(content: string): { text: string; weight: string[]; unknown: string[]; tension?: string } | null {
  const raw = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  let v: unknown;
  try {
    v = JSON.parse(raw);
  } catch {
    return null;
  }
  if (typeof v !== 'object' || v === null || Array.isArray(v)) return null;
  const o = v as Record<string, unknown>;
  const strings = (a: unknown) => Array.isArray(a) && a.every((x) => typeof x === 'string');
  if (typeof o.text !== 'string' || !strings(o.weight) || !strings(o.unknown)) return null;
  if (o.tension !== undefined && typeof o.tension !== 'string') return null;
  return {
    text: o.text,
    weight: o.weight as string[],
    unknown: o.unknown as string[],
    ...(o.tension !== undefined ? { tension: o.tension as string } : {}),
  };
}

function empty(status: Debate['status']): Debate {
  return { status, shown: false, sound: '', fragile: '', reviewer: '', weight: [], unknown: [], models: {}, usd: 0, rejected: [] };
}

export async function debate(input: DebateInput, deps: DebateDeps): Promise<Debate> {
  const mode: Mode = deps.mode ?? 'shadow';
  if (mode === 'off') return empty('off');

  const result = await run(input, deps);
  result.shown = mode === 'on' && result.status === 'ok';
  if (mode === 'shadow' && deps.log) {
    try {
      deps.log(result);
    } catch {
      // a failing log never breaks the debate
    }
  }
  return result;
}

async function run(input: DebateInput, deps: DebateDeps): Promise<Debate> {
  const timeoutMs = deps.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const facts = new Set(numbersIn(input.facts_text));
  const out = empty('ok');
  const timers: ReturnType<typeof setTimeout>[] = [];

  const call = async (args: RouteArgs): Promise<RouteResult> => {
    const timer = new Promise<never>((_, reject) => {
      timers.push(setTimeout(() => reject(new TimeoutError()), timeoutMs));
    });
    const res = await Promise.race([Promise.resolve().then(() => deps.route(args)), timer]);
    if (typeof res?.cost_usd === 'number' && Number.isFinite(res.cost_usd)) out.usd += res.cost_usd;
    if (res?.model) out.models[args.payload.role] = res.model;
    return res;
  };

  try {
    const prompt = factsPrompt(input);
    const roles = ['sound', 'fragile'] as const;
    const advocates = await Promise.allSettled(
      roles.map((role) => call(routeArgs(role, advocateSystem(role), prompt, 400))),
    );
    for (let i = 0; i < roles.length; i++) {
      const role = roles[i];
      const r = advocates[i];
      if (r.status === 'rejected') {
        if (r.reason instanceof TimeoutError) return timedOut(out);
        out[role] = NO_CASE;
        out.rejected.push(`${role}: call failed`);
        continue;
      }
      const text = typeof r.value?.content === 'string' ? r.value.content.trim() : '';
      const problems = text ? checkPart(text, facts, ADVOCATE_MAX_WORDS, deps.check) : ['empty answer'];
      if (problems.length) {
        out[role] = NO_CASE;
        for (const p of problems) out.rejected.push(`${role}: ${p}`);
      } else {
        out[role] = text;
      }
    }

    const reviewerPrompt = [
      prompt,
      '',
      'Sound structure advocate:',
      out.sound,
      '',
      'Fragile structure advocate:',
      out.fragile,
    ].join('\n');
    let res: RouteResult;
    try {
      res = await call(routeArgs('reviewer', reviewerSystem(), reviewerPrompt, 600));
    } catch (e) {
      if (e instanceof TimeoutError) return timedOut(out);
      return reject(out, ['reviewer: call failed']);
    }
    const parsed = typeof res?.content === 'string' ? parseReviewer(res.content) : null;
    if (!parsed) return reject(out, ['reviewer: unparseable JSON']);

    const problems = checkPart(parsed.text, facts, REVIEWER_MAX_WORDS, deps.check).map((p) => `reviewer: ${p}`);
    if (parsed.tension !== undefined) {
      for (const p of checkPart(parsed.tension, facts, REVIEWER_MAX_WORDS, deps.check)) problems.push(`reviewer tension: ${p}`);
    }
    if (problems.length) return reject(out, problems);

    const known = new Set(input.flag_ids);
    out.reviewer = parsed.text.trim();
    out.weight = [...new Set(parsed.weight.filter((id) => known.has(id)))];
    out.unknown = parsed.unknown
      .map((u) => u.trim())
      .filter((u) => u && checkPart(u, facts, REVIEWER_MAX_WORDS, deps.check).length === 0);
    if (parsed.tension !== undefined && parsed.tension.trim()) out.tension = parsed.tension.trim();
    return out;
  } finally {
    for (const t of timers) clearTimeout(t);
  }
}

function clearTexts(out: Debate): void {
  out.sound = '';
  out.fragile = '';
  out.reviewer = '';
  out.weight = [];
  out.unknown = [];
  delete out.tension;
}

function reject(out: Debate, reasons: string[]): Debate {
  clearTexts(out);
  out.status = 'rejected';
  out.rejected.push(...reasons);
  return out;
}

function timedOut(out: Debate): Debate {
  clearTexts(out);
  out.status = 'timeout';
  return out;
}
