    'Liquidity pool holds 182,400 USD, locked for 90 days.',
    'Mint authority is revoked.',
    'Token age is 12 days.',
  ].join('\n'),
  level: 'medium',
  points: 46,
  flag_ids: ['top10_concentration', 'young_token'],
  unknown: ['team wallets'],
};

const SOUND = 'Mint authority is revoked and the pool of 182,400 USD is locked for 90 days, so supply and liquidity cannot be changed at will.';
const FRAGILE = 'Top 10 holders own 41.7 percent of the supply and the token is 12 days old, so a few wallets weigh heavily on a short history.';
const REVIEW = { text: 'Concentration of 41.7 percent at 12 days is the main weight; the lock of 90 days limits liquidity risk.', weight: ['top10_concentration', 'young_token', 'made_up'], unknown: ['team wallets'], tension: 'Whether the lock offsets the concentration.' };

type Script = Partial<Record<'sound' | 'fragile' | 'reviewer', string | ((a: RouteArgs) => Promise<RouteResult>)>>;

function fakeRoute(script: Script = {}) {
  const calls: { args: RouteArgs; at: number; done?: number }[] = [];
  const defaults = { sound: SOUND, fragile: FRAGILE, reviewer: JSON.stringify(REVIEW) };
  const route = async (args: RouteArgs): Promise<RouteResult> => {
    const entry = { args, at: calls.length };
    calls.push(entry);
    const role = args.payload.role;
    const s = script[role] ?? defaults[role];
    if (typeof s === 'function') return s(args);
    await new Promise((r) => setTimeout(r, 5));
    return { content: s, model: `model-${role}`, cost_usd: role === 'reviewer' ? 0.02 : 0.005 };
  };
  return { route, calls };
}

test('A1 advocates run in parallel with roles sound and fragile, then the reviewer with both texts and the facts', async () => {
  let inFlight = 0;
  let maxInFlight = 0;
  const seen: RouteArgs[] = [];
  const route = async (args: RouteArgs): Promise<RouteResult> => {
    seen.push(args);
    inFlight++;
    maxInFlight = Math.max(maxInFlight, inFlight);
    await new Promise((r) => setTimeout(r, 20));
    inFlight--;
    const role = args.payload.role;
    return { content: role === 'sound' ? SOUND : role === 'fragile' ? FRAGILE : JSON.stringify(REVIEW) };
  };
  const d = await debate(input, { route, mode: 'on' });
  assert.equal(d.status, 'ok');
  assert.deepEqual(seen.map((a) => a.payload.role), ['sound', 'fragile', 'reviewer']);
  assert.equal(maxInFlight, 2);
  for (const a of seen) {
    assert.equal(a.task_type, 'risk_debate');
    assert.equal(a.tier_class, 'text');
    assert.equal(a.constitutional_flag, false);
    assert.equal(a.agent_id, 'golden-kog');
    assert.ok(a.context_tokens > 0);
    assert.ok(a.payload.prompt.includes(input.facts_text));
  }
  assert.equal(seen[0].complexity, 'exec');
  assert.equal(seen[1].complexity, 'exec');
  assert.equal(seen[2].complexity, 'apex');
  assert.ok(seen[2].payload.prompt.includes(SOUND));
  assert.ok(seen[2].payload.prompt.includes(FRAGILE));
  assert.equal(d.sound, SOUND);
  assert.equal(d.fragile, FRAGILE);
  assert.equal(d.reviewer, REVIEW.text);
});

