    ['A clear Entry here.', 'refused word: entry'],
    ['Wait for a price   target.', 'refused word: price target'],
    ['Mint authority is revoked — good.', 'dash character'],
    ['Mint authority is revoked - good.', 'dash character'],
    ['Token age is ١٢ days.', 'non Latin digit'],
    [Array(181).fill('word').join(' '), '181 words, over 180'],
    ['Mint authority is revoked.', 'check: guard said no'],
  ];
