  const { route } = fakeRoute({ sound: 'Mint authority is revoked, bearing no reentry of supply.' });
  assert.equal((await debate(input, { route })).sound, 'Mint authority is revoked, bearing no reentry of supply.');
  // the reviewer has its own limit of 150 words
  const long = fakeRoute({ reviewer: JSON.stringify({ ...REVIEW, text: Array(151).fill('word').join(' ') }) });
  const d = await debate(input, { route: long.route });
  assert.equal(d.status, 'rejected');
  assert.ok(d.rejected.includes('reviewer: 151 words, over 150'));
